"""Read-only host metadata; no mounts, sudo, service mutations or remote filesystem traversal."""
from datetime import datetime,timezone
from pathlib import Path
import grp,json,os,platform,pwd,re,shlex,shutil,stat,subprocess,sys

def read(path,limit=65536):
 try:
  with open(path,'r') as f:return {'text':f.read(limit)}
 except OSError as e:return {'error':str(e)}

def command(args):
 try:
  p=subprocess.run(args,capture_output=True,text=True,timeout=3)
  return {'command':args,'returncode':p.returncode,'stdout':p.stdout[:65536],'stderr':p.stderr[:4096]}
 except (OSError,subprocess.TimeoutExpired) as e:return {'command':args,'error':str(e)}

def decode(value):return re.sub(r'\\([0-7]{3})',lambda m:chr(int(m[1],8)),value)
mounts=[]
for line in read('/proc/self/mountinfo',1024*1024).get('text','').splitlines():
 left,right=line.split(' - ',1);a,b=left.split(),right.split()
 mounts.append({'target':decode(a[4]),'fstype':b[0],'source':decode(b[1]),'options':a[5]+','+b[2]})
def mount_for(path):
 matches=[m for m in mounts if path==m['target'] or path.startswith(m['target'].rstrip('/')+'/')]
 return max(matches,key=lambda m:len(m['target'])) if matches else None

def path_info(path):
 path=Path(path)
 row={'path':str(path)}
 for parent in [*reversed(path.parents),path]:
  mount=mount_for(str(parent))
  if mount and mount['fstype'] not in ('ext4','ext3','ext2','xfs','btrfs','f2fs','overlay','tmpfs','vfat'):
   row.update(skipped='Avoid nonlocal or automount traversal',mount=mount);return row
  try:
   info=parent.lstat()
   if stat.S_ISLNK(info.st_mode):row.update(skipped='Symlink ancestor or target',symlink=str(parent),target=os.readlink(parent));return row
  except OSError as e:row['error']=str(e);return row
 try:
  info=path.lstat();disk=os.statvfs(path)
  row.update(uid=info.st_uid,gid=info.st_gid,mode=oct(stat.S_IMODE(info.st_mode)),is_directory=stat.S_ISDIR(info.st_mode),free_bytes=disk.f_bavail*disk.f_frsize,free_inodes=disk.f_favail,mount=mount_for(str(path)))
  try:row['user']=pwd.getpwuid(info.st_uid).pw_name
  except KeyError:pass
  try:row['group']=grp.getgrgid(info.st_gid).gr_name
  except KeyError:pass
 except OSError as e:row['error']=str(e)
 return row

root=Path(sys.argv[1]);root=root if root.is_absolute() else Path.home()/root
routes=json.loads(sys.argv[2]) if len(sys.argv)>2 else []
r={'observed_at_utc':datetime.now(timezone.utc).isoformat(),'hostname':platform.node(),'architecture':platform.machine(),'kernel':platform.release(),'python':platform.python_version(),'uid':os.getuid(),'gid':os.getgid(),'ssh_connection':os.environ.get('SSH_CONNECTION'),'root':str(root),'os_release':read('/etc/os-release'),'network_addresses':command(['ip','-j','address','show']),'network_routes':command(['ip','-j','route','show']),'routes_to_observed_peers':{ip:command(['ip','-j','route','get',ip]) for ip in routes},'link_state':{},'paths':{},'nfs_mounts':[m for m in mounts if m['fstype'] in ('nfs','nfs4')],'automounts':[m for m in mounts if m['fstype']=='autofs'],'nfs_tools':{}}
for interface in Path('/sys/class/net').iterdir():
 r['link_state'][interface.name]={name:read(interface/name,256) for name in ('operstate','carrier','speed','mtu')}
for path in [Path('/'),Path('/srv'),Path('/srv/ml-shared'),Path('/srv/ml-shared/objects'),Path('/srv/nfs/cifar10_data'),Path('/mnt'),Path('/mnt/nfs_share'),root,root/'worker-storage',root/'worker-storage/inputs',root/'storage',root/'controller/jobs.db']:
 r['paths'][str(path)]=path_info(path)
for name in ('exportfs','mount.nfs','nfsstat','rpcinfo','findmnt','ip','ss'):
 candidates=[shutil.which(name),'/usr/sbin/'+name,'/sbin/'+name]
 r['nfs_tools'][name]=next((p for p in candidates if p and os.path.isfile(p) and os.access(p,os.X_OK)),None)
r['nfs_packages']=command(['dpkg-query','-W','-f=${Package} ${Status} ${Version}\n','nfs-common','nfs-kernel-server','rpcbind'])
r['kernel_nfs_filesystems']=[line for line in read('/proc/filesystems').get('text','').splitlines() if 'nfs' in line]
r['nfsd_versions']=read('/proc/fs/nfsd/versions')
r['active_kernel_exports']=read('/proc/fs/nfsd/exports')
r['managed_export_table']=read('/var/lib/nfs/etab')
r['exports_files']={}
exports=[Path('/etc/exports')]
try:exports+=list(Path('/etc/exports.d').glob('*.exports'))
except OSError as e:r['exports_directory_error']=str(e)
for p in exports:
 result=read(p)
 if 'text' in result:result['noncomment_lines']=[line for line in result.pop('text').splitlines() if line.strip() and not line.lstrip().startswith('#')]
 result['permissions']=path_info(p)
 r['exports_files'][str(p)]=result
r['export_directory_permissions']=path_info('/etc/exports.d')
r['fstab_nfs_entries']={}
fstab=read('/etc/fstab')
if 'text' in fstab:r['fstab_nfs_entries']['lines']=[line for line in fstab['text'].splitlines() if not line.lstrip().startswith('#') and len(line.split())>=3 and line.split()[2] in ('nfs','nfs4','autofs')]
else:r['fstab_nfs_entries']=fstab
ports=command(['ss','-ltn'])
if 'stdout' in ports:ports['stdout']='\n'.join(line for line in ports['stdout'].splitlines() if any(re.search(r':'+str(port)+r'\b',line) for port in (111,2049,5000,8080)))
r['relevant_tcp_listeners']=ports
r['nfs_service']=command(['systemctl','show','nfs-server.service','nfs-kernel-server.service','rpcbind.service','nfs-client.target','--no-pager','--property=Id','--property=LoadState','--property=ActiveState','--property=SubState','--property=FragmentPath'])
props=['ActiveState','SubState','User','Group','WorkingDirectory','MainPID','PrivateMounts','ProtectSystem','ProtectHome','NoNewPrivileges','ReadOnlyPaths','InaccessiblePaths']
r['agent_service']=command(['systemctl','show','dl-node-agent.service','--no-pager',*['--property='+p for p in props]])
r['controller_services']=command(['systemctl','--user','show','dl-dispatcher.service','dl-student-portal.service','--no-pager','--property=Id','--property=ActiveState','--property=SubState'])
r['probe_mount_namespace']=os.readlink('/proc/self/ns/mnt')
try:
 pid=next((line.split('=',1)[1] for line in r['agent_service'].get('stdout','').splitlines() if line.startswith('MainPID=')),'0')
 if int(pid)>0:r['agent_mount_namespace']=os.readlink('/proc/'+pid+'/ns/mnt')
except (OSError,ValueError) as e:r['agent_namespace_error']=str(e)
print(json.dumps(r,sort_keys=True))

