from concurrent.futures import ThreadPoolExecutor
from datetime import datetime,timezone
from pathlib import Path
import json,shlex,subprocess,time,urllib.request
run=Path(__file__).resolve().parent
app=Path('/home/rana/Projects/System Project/System_Development_Project/distributed-dl-system')
nodes=[node for node in json.loads((app/'config/nodes.json').read_text())['nodes'] if node['id'] in ('pi02','pi03')]
controller=json.loads((run/'controller-current.json').read_text()) if (run/'controller-current.json').exists() else json.loads((run/'controller-sandbox.json').read_text())
try:interfaces=json.loads(controller['network_addresses'].get('stdout','[]'))
except ValueError:interfaces=[]
peers=[a['local'] for i in interfaces if i.get('operstate')=='UP' and i['ifname'] not in ('lo','tailscale0') for a in i.get('addr_info',[]) if a.get('family')=='inet' and a.get('scope')=='global']
script=(run/'host_probe.py').read_text()

def probe(node):
 cmd=['ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=5','-o','ConnectionAttempts=1','-o','StrictHostKeyChecking=yes','-o','UpdateHostKeys=no','-o','ControlMaster=no','-o','ControlPath=none','-o','ControlPersist=no','-o','ForwardAgent=no','-o','ClearAllForwardings=yes','-o','PermitLocalCommand=no','-o','RemoteCommand=none','-o','ServerAliveInterval=4','-o','ServerAliveCountMax=1',node['id'],shlex.join(['python3','-I','-B','-',node.get('worker_root','distributed-dl-system'),json.dumps(peers)])]
 row={'node':node['id'],'inventory_address':node['ip'],'observed_at_utc':datetime.now(timezone.utc).isoformat(),'ssh':{'command':cmd},'http':{}}
 try:
  start=time.monotonic();p=subprocess.run(cmd,input=script,capture_output=True,text=True,timeout=40)
  row['ssh'].update(returncode=p.returncode,stderr=p.stderr[:4096],elapsed_seconds=round(time.monotonic()-start,3))
  if p.returncode==0:
   try:row['ssh']['data']=json.loads(p.stdout)
   except ValueError:row['ssh']['unexpected_stdout']=p.stdout[:4096]
 except (OSError,subprocess.TimeoutExpired) as e:row['ssh']['error']=str(e)
 opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
 for route in ('health','resources'):
  url=f"http://{node['ip']}:{node['port']}/{route}"
  try:
   with opener.open(url,timeout=3) as response:
    value=json.loads(response.read(131072))
    names=('node','status','architecture','python','execution_ownership') if route=='health' else ('node','node_state','timestamp','slots','disk','network')
    row['http'][route]={'url':url,'status':response.status,'identity_matches':value.get('node')==node['id'],'data':{k:value.get(k) for k in names}}
  except (OSError,ValueError) as e:row['http'][route]={'url':url,'error':str(e)}
 return row
with ThreadPoolExecutor(max_workers=3) as pool:rows=list(pool.map(probe,nodes))
(run/'cluster-current.json').write_text(json.dumps(rows,indent=2)+'\n')
for r in rows:print(json.dumps({'node':r['node'],'ssh':r['ssh'].get('returncode',r['ssh'].get('error')),'ssh_error':r['ssh'].get('stderr'),'http':{k:v.get('status',v.get('error')) for k,v in r['http'].items()}}),flush=True)
